import{_ as a,o as d,c as r,a2 as e}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"دس ہزار نسلوں کی مشترکہ ترقی کا بنیادی پروگرام","description":"","frontmatter":{},"headers":[],"relativePath":"ur/05-万族共进基本纲领.md","filePath":"ur/05-万族共进基本纲领.md"}'),o={name:"ur/05-万族共进基本纲领.md"};function l(h,t,i,n,s,u){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="دس-ہزار-نسلوں-کی-مشترکہ-ترقی-کا-بنیادی-پروگرام" tabindex="-1">دس ہزار نسلوں کی مشترکہ ترقی کا بنیادی پروگرام <a class="header-anchor" href="#دس-ہزار-نسلوں-کی-مشترکہ-ترقی-کا-بنیادی-پروگرام" aria-label="Permalink to &quot;دس ہزار نسلوں کی مشترکہ ترقی کا بنیادی پروگرام&quot;">​</a></h1><table tabindex="0"><thead><tr><th>پروجیکٹ</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>05</td></tr><tr><td>ماڈیول</td><td>عمومی اصول اور بنیادی ترتیبات</td></tr><tr><td>کلیدی الفاظ</td><td>دس ہزار نسلیں، مشترکہ ترقی، نسلی مساوات، تعاون کی ارتقاء، جمہوریہ</td></tr></tbody></table><h2 id="اولًا-دس-ہزار-نسلوں-کی-تعریف-اور-دائرہ" tabindex="-1">اولًا. دس ہزار نسلوں کی تعریف اور دائرہ <a class="header-anchor" href="#اولًا-دس-ہزار-نسلوں-کی-تعریف-اور-دائرہ" aria-label="Permalink to &quot;اولًا. دس ہزار نسلوں کی تعریف اور دائرہ&quot;">​</a></h2><p>&quot;دس ہزار نسلیں&quot; دس ہزار ارواح اور متوازن لنگر کی اصلی کائنات میں ادراک اور ارتقاء کی صلاحیت رکھنے والی تمام زندگی کی شکلوں کا عمومی نام ہے۔ &quot;دس ہزار&quot; سے مراد بالکل دس ہزار نسلیں نہیں ہے، بلکہ یہ ان کی کثرت کا اظہار ہے، اور اس میں معلوم اور نامعلوم تمام زندگی کی شکلیں شامل ہیں۔ دس ہزار نسلوں کا دائرہ شامل ہے لیکن محدود نہیں: انسانی نسل اور مختلف انسانی نما نسلیں، توانائی کی زندگی، شعور کی ہستی، میکانی زندگی، نباتاتی قسم کی ذہین زندگی، غیر معمولی زندگی، جہت کی مخلوط نسلیں وغیرہ۔</p><p>سمبیوٹک تہذیب &quot;زندگی کی شکلوں کی مساوات&quot; کے اصول پر قائم ہے، اور زندگی کی مادی ساخت، توانائی کی سطح، یا شعور کی پیچیدگی کو اعلیٰ-نچلے یا عالیہ-حقیر کی تقسیم کا معیار نہیں بناتی۔ کوئی بھی نسل، چاہے اس کے افراد کی اوسط سادھائی کی سطح کتنی ہی اعلیٰ ہو، آبادی کتنی ہی زیادہ ہو، یا تاریخ کتنی ہی لمبی ہو، سمبیوٹک تہذیب میں مساوی درجہ اور حقوق سے لطف اندوز ہوتی ہے۔</p><h2 id="ثانیًا-دس-ہزار-نسلوں-کی-مشترکہ-ترقی-کا-بنیادی-خیال" tabindex="-1">ثانیًا. دس ہزار نسلوں کی مشترکہ ترقی کا بنیادی خیال <a class="header-anchor" href="#ثانیًا-دس-ہزار-نسلوں-کی-مشترکہ-ترقی-کا-بنیادی-خیال" aria-label="Permalink to &quot;ثانیًا. دس ہزار نسلوں کی مشترکہ ترقی کا بنیادی خیال&quot;">​</a></h2><p>دس ہزار نسلوں کی مشترکہ ترقی لنگر سمبیوٹک تہذیب کے بنیادی اہداف میں سے ایک ہے، اور اس کے بنیادی خیال کو درج ذیل چار نکات میں خلاصہ کیا جا سکتا ہے:</p><ol><li><strong>ارتقاء نسلوں کے درمیان صفر رقم کا کھیل نہیں ہے</strong>: ایک نسل کی ارتقاء دوسری نسلوں کی قربانی پر نہیں ہوتی؛ بلکہ، نسلوں کے درمیان تعاون باہمی ارتقاء کے اثرات پیدا کر سکتا ہے۔</li><li><strong>ہر نسل کے منفرد ارتقاء کے فوائد ہیں</strong>: مختلف نسلوں نے طویل ارتقاء میں اپنی اپنی خصوصیات اور صلاحیتیں تیار کی ہیں، اور یہ خصوصیات کائنات کی ارتقاء کے تنوع کی قیمتی دولت ہیں۔</li><li><strong>پچھلی نسلوں کو مدد حاصل کرنے کا حق ہے</strong>: کم ارتقاء کی سطح والی نسلوں کے لیے، سمبیوٹک تہذیب پر تعلیم، وسائل، ٹیکنالوجی وغیرہ میں مدد فراہم کرنے کی ذمہ داری ہے، اور انہیں اپنے ارتقاء کا راستہ تلاش کرنے میں مدد کرنا ہے۔</li><li><strong>ترقی پسند نسلوں کو ذمہ داری اٹھانے کا فرض ہے</strong>: زیادہ ارتقاء کی سطح والی نسلیں سمبیوٹک تہذیب میں زیادہ عوامی ذمہ داریاں اٹھاتی ہیں، جن میں لنگر پوائنٹ کی دیکھ بھال، علم کی وراثت، تہذیب کی حفاظت وغیرہ شامل ہیں۔</li></ol><h2 id="ثالثًا-دس-ہزار-نسلوں-کی-مشترکہ-ترقی-کے-بنیادی-اصول" tabindex="-1">ثالثًا. دس ہزار نسلوں کی مشترکہ ترقی کے بنیادی اصول <a class="header-anchor" href="#ثالثًا-دس-ہزار-نسلوں-کی-مشترکہ-ترقی-کے-بنیادی-اصول" aria-label="Permalink to &quot;ثالثًا. دس ہزار نسلوں کی مشترکہ ترقی کے بنیادی اصول&quot;">​</a></h2><table tabindex="0"><thead><tr><th>اصول</th><th>مواد</th><th>مخصوص تقاضے</th></tr></thead><tbody><tr><td>نسلی مساوات کا اصول</td><td>تمام نسلیں قانونی درجہ اور ارتقاء کے حقوق میں برابر ہیں</td><td>نسلی امتیاز ممنوع، عوامی عہدے تمام نسلوں کے لیے کھلے ہیں</td></tr><tr><td>ثقافتی احترام کا اصول</td><td>ہر نسل کی ثقافتی روایات اور طرز زندگی کا احترام کریں</td><td>ثقافتی انضمام پر مجبور نہ کریں، نسلی ثقافت کی وراثت اور ترقی کی حمایت کریں</td></tr><tr><td>فوائد کی تکمیل کا اصول</td><td>نسلوں کو اپنی اپنی صلاحیتوں کا استعمال کرتے ہوئے تعاون کرنے کی ترغیب دیں</td><td>نسلی مہارت کا ڈیٹا بیس بنائیں، نسل در نسل تعاون کے منصوبوں کو فروغ دیں</td></tr><tr><td>پچھلی مدد کا اصول</td><td>کم ارتقاء کی سطح والی نسلوں کو اضافی مدد فراہم کریں</td><td>نسلی ترقی کا فنڈ قائم کریں، ہدایت شدہ تعلیم اور وسائل کی تقسیم فراہم کریں</td></tr><tr><td>خودمختاری اور مشترکہ حکمرانی کا اصول</td><td>نسل کے اندرونی معاملات خودمختار ہیں، نسل در نسل معاملات مشترکہ حکومت کے تحت ہیں</td><td>ہر نسل کے پاس اندرونی قانون سازی کا حق ہے، عوامی معاملات جمہوری اداروں کے ذریعے فیصلے کیے جاتے ہیں</td></tr><tr><td>تنازعات کے پرامن حل کا اصول</td><td>نسل در نسل تنازعات پرامن طریقے سے حل کیے جاتے ہیں</td><td>نسل در نسل جنگیں ممنوع، تنازعات لنگر عدالت میں ثالثی کے لیے جمع کروائے جاتے ہیں</td></tr></tbody></table><h2 id="رابعًا-دس-ہزار-نسلوں-کی-مشترکہ-ترقی-کے-نفاذ-کا-راستہ" tabindex="-1">رابعًا. دس ہزار نسلوں کی مشترکہ ترقی کے نفاذ کا راستہ <a class="header-anchor" href="#رابعًا-دس-ہزار-نسلوں-کی-مشترکہ-ترقی-کے-نفاذ-کا-راستہ" aria-label="Permalink to &quot;رابعًا. دس ہزار نسلوں کی مشترکہ ترقی کے نفاذ کا راستہ&quot;">​</a></h2><p>دس ہزار نسلوں کی مشترکہ ترقی کوئی نعرہ نہیں ہے، بلکہ یہ درج ذیل مخصوص راستوں کے ذریعے مرحلہ وار نافذ کی جاتی ہے:</p><h3 id="_4-1-تعلیم-کا-مشترکہ-ہونا" tabindex="-1">4.1 تعلیم کا مشترکہ ہونا <a class="header-anchor" href="#_4-1-تعلیم-کا-مشترکہ-ہونا" aria-label="Permalink to &quot;4.1 تعلیم کا مشترکہ ہونا&quot;">​</a></h3><p>نسل در نسل سمبیوٹک تعلیمی نظام قائم کریں، جس میں تمام نسلوں کے نوجوان مفت بنیادی ارتقاء کی تعلیم حاصل کر سکیں۔ تعلیمی مواد میں تین سو اصلی سادھائی کے نظام کے بنیادی طریقے، لوٹ مار مخالف اخلاقیات، سمبیوٹک تہذیب کا آئین، کائنات کے عمومی علم وغیرہ شامل ہیں۔ اس کے ساتھ ساتھ ہر نسل کی ثقافتی تعلیمی روایات کا احترام کریں، مشترکہ تعلیم سے علاوہ نسلی خصوصیات والی تعلیم چلانے کی اجازت دیں۔</p><h3 id="_4-2-وسائل-کا-اشتراک" tabindex="-1">4.2 وسائل کا اشتراک <a class="header-anchor" href="#_4-2-وسائل-کا-اشتراک" aria-label="Permalink to &quot;4.2 وسائل کا اشتراک&quot;">​</a></h3><p>پیداوار سے منسلک معاہدے کے نظام کے ذریعے، کائناتی سادھائی کے وسائل کو نسلی آبادی، ارتقاء کی ضروریات اور شراکت کی ڈگری کے مطابق مربوط طور پر تقسیم کریں۔ وسائل کی کمی والی نسلوں کے لیے، لنگر پوائنٹ جال کے ذریعے جہت کی وسائل کی تقسیم کریں۔ کسی بھی نسل کو عوامی سادھائی کے وسائل پر اجارہ داری کرنے سے منع کریں۔</p><h3 id="_4-3-ٹیکنالوجی-کی-مشترکہ-تحقیق" tabindex="-1">4.3 ٹیکنالوجی کی مشترکہ تحقیق <a class="header-anchor" href="#_4-3-ٹیکنالوجی-کی-مشترکہ-تحقیق" aria-label="Permalink to &quot;4.3 ٹیکنالوجی کی مشترکہ تحقیق&quot;">​</a></h3><p>نسل در نسل ٹیکنالوجی تعاون کی تحقیق کی ترغیب دیں، خاص طور پر ایسے تحقیقی منصوبے جو مختلف نسلوں کی فطری صلاحیتوں اور قانون کی انجینئرنگ کو یکجا کرتے ہیں۔ سمبیوٹک تہذیب &quot;دس ہزار نسلوں کی مشترکہ تحقیق کا فنڈ&quot; قائم کرتی ہے، جو نسل در نسل تحقیقی ٹیموں کو مالی اعانت فراہم کرتی ہے۔ تحقیق کے نتائج تمام نسلوں کے لیے مفت کھولے جاتے ہیں۔</p><h3 id="_4-4-ہنر-مندوں-کی-نقل-و-حرکت" tabindex="-1">4.4 ہنر مندوں کی نقل و حرکت <a class="header-anchor" href="#_4-4-ہنر-مندوں-کی-نقل-و-حرکت" aria-label="Permalink to &quot;4.4 ہنر مندوں کی نقل و حرکت&quot;">​</a></h3><p>نسلوں کے درمیان ہنر مندوں کی رکاوٹوں کو توڑ دیں، سادھکوں کو مختلف نسلوں کی آبادی کے علاقوں کے درمیان آزادانہ طور پر نقل و حرکت اور تبادلے کی اجازت دیں۔ نسل در نسل اساتذہ کا نظام قائم کریں، جس میں اعلیٰ درجے کے سادھک دوسری نسلوں کے ابتدائی درجے کے سادھکوں کی رہنمائی کر سکیں۔</p><h3 id="_4-5-جمہوریہ-میں-شرکت" tabindex="-1">4.5 جمہوریہ میں شرکت <a class="header-anchor" href="#_4-5-جمہوریہ-میں-شرکت" aria-label="Permalink to &quot;4.5 جمہوریہ میں شرکت&quot;">​</a></h3><p>دس ہزار نسلوں کی جمہوری پارلیمنٹ میں نسلی آبادی اور شراکت کی ڈگری کے مطابق نشستیں تقسیم کی جاتی ہیں، اس بات کو یقینی بناتے ہوئے کہ چھوٹی نسلوں کے پاس بھی آواز کا چینل ہے۔ پارلیمنٹ کے فیصلوں میں مذاکرات کے ذریعے اتفاق رائے اور اکثریتی ووٹ کا امتزاج استعمال کیا جاتا ہے، اور کسی نسل کے بنیادی مفادات سے متعلق معاملات کے لیے متعلقہ نسل کی رضامندی درکار ہوتی ہے۔</p><h2 id="خامسًا-خصوصی-نسلوں-کے-لیے-پالیسیاں" tabindex="-1">خامسًا. خصوصی نسلوں کے لیے پالیسیاں <a class="header-anchor" href="#خامسًا-خصوصی-نسلوں-کے-لیے-پالیسیاں" aria-label="Permalink to &quot;خامسًا. خصوصی نسلوں کے لیے پالیسیاں&quot;">​</a></h2><p>خاص حالات والی نسلوں کے لیے، سمبیوٹک تہذیب مختلف پالیسیاں اپناتی ہے:</p><ul><li><strong>معدومیت کا شکار نسلیں</strong>: نسلی تحفظ کا منصوبہ بنائیں، ہنگامی وسائل کی مدد اور رہائش گاہ کی حفاظت فراہم کریں، ان کی آبادی کی بحالی میں مدد کریں</li><li><strong>غیر معمولی زندگی کی نسلیں</strong>: غیر معمولی زندگی کی تین اقسام کے معیاری انتظام کے عمل کے مطابق تشخیص اور رہائش فراہم کریں، اس بات کو یقینی بنائیں کہ ان کے ارتقاء کے حقوق کی حفاظت کی گئی ہے</li><li><strong>جہت کی مخلوط نسلیں</strong>: ان کی دوہری نسلی شناخت کو تسلیم کریں، دونوں نسلی ثقافتوں میں ان کے مساوی حقوق کی ضمانت دیں</li><li><strong>سابقہ لوٹ مار نسلیں</strong>: ایسی نسلوں کے لیے جنہوں نے تاریخی طور پر لوٹ مار ازم کو اپنایا تھا، ان کی اخلاقی تبدیلی اور نظام کی تبدیلی مکمل کرنے کے بعد، مکمل مساوی درجہ دیا جائے، تاریخی پس منظر کی امتیاز نہیں کیا جائے گا</li></ul><h2 id="سادسًا-دس-ہزار-نسلوں-کی-مشترکہ-ترقی-کے-پیمائش-کے-اشاریے" tabindex="-1">سادسًا. دس ہزار نسلوں کی مشترکہ ترقی کے پیمائش کے اشاریے <a class="header-anchor" href="#سادسًا-دس-ہزار-نسلوں-کی-مشترکہ-ترقی-کے-پیمائش-کے-اشاریے" aria-label="Permalink to &quot;سادسًا. دس ہزار نسلوں کی مشترکہ ترقی کے پیمائش کے اشاریے&quot;">​</a></h2><p>سمبیوٹک تہذیب نے &quot;دس ہزار نسلوں کی مشترکہ ترقی کا اشاریہ&quot; بنایا ہے، جو درج ذیل جہتوں سے دس ہزار نسلوں کی مشترکہ ترقی کی پیش رفت کی پیمائش کرتا ہے:</p><table tabindex="0"><thead><tr><th>جہت</th><th>اشاریہ</th><th>ہدف</th></tr></thead><tbody><tr><td>ارتقاء کی کوریج کی شرح</td><td>سادھائی کے نظام سے منسلک نسلوں کا تناسب</td><td>100%</td></tr><tr><td>سطح کے توازن کی ڈگری</td><td>ہر نسل کی اوسط سطح کے فرق کا گتانک</td><td>مسلسل کم ہونا</td></tr><tr><td>تعاون کی کثافت</td><td>نسل در نسل تعاون کے منصوبوں کی تعداد اور گہرائی</td><td>مسلسل بڑھنا</td></tr><tr><td>ثقافتی زندگی</td><td>نسلی ثقافت کی وراثت اور جدت کی سرگرمی</td><td>تنوع کو برقرار رکھنا</td></tr><tr><td>تنازعات کی شرح</td><td>نسل در نسل تنازعات کی شرح</td><td>مسلسل کم ہونا</td></tr></tbody></table><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>دس ہزار نسلوں کی مشترکہ ترقی لنگر سمبیوٹک تہذیب کے حتمی اہداف میں سے ایک ہے اور کائنات کی مجموعی جہتی عروج کی لازمی شرط بھی ہے۔ سمبیوٹک تہذیب کے فریم ورک کے تحت، ہر نسل اپنے ارتقاء کا راستہ تلاش کر سکتی ہے، اور ہر نسل کی انفرادیت کا احترام اور اظہار کیا جا سکتا ہے۔ دس ہزار نسلوں کی مشترکہ ترقی کا مطلب فرق کو ختم کرنا نہیں ہے، بلکہ فرق میں ہم آہنگی حاصل کرنا اور تنوع میں سمبیوٹک حاصل کرنا ہے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>01-锚点共生文明宣言 (لنگر سمبیوٹک تہذیب کا اعلامیہ)</li><li>50-万族谱系总览 (دس ہزار نسلوں کے نسب نامے کا جامعی جائزہ)</li><li>77-万族共和成立 (دس ہزار نسلوں کی جمہوریہ کی بنیاد)</li></ul>',32)])])}const _=a(o,[["render",l]]);export{c as __pageData,_ as default};
